mkdir -p scratch/chopperMotorbike && cat > scratch/chopperMotorbike/probe.ts <<'EOF'
import * as THREE from "three";
import build from "../../samples/chopperMotorbike";
const root = build();
const box = new THREE.Box3().setFromObject(root, true);
let parts = 0, tris = 0;
const joints: string[] = [];
root.traverse((o) => {
  if ((o as THREE.Mesh).isMesh) { parts++; const g = (o as THREE.Mesh).geometry; tris += (g.index ? g.index.count : g.attributes.position.count) / 3; }
  if (o.type === "Group" || (o as any).isBone) joints.push(o.name);
});
console.log("parts", parts, "tris", tris, "box", box.min.toArray().map(n=>n.toFixed(3)), box.max.toArray().map(n=>n.toFixed(3)));
console.log("joints", joints.length, joints.join(","));
EOF
npx tsx scratch/chopperMotorbike/probe.ts 2>&1 | tail -30
